package com.ruoyi.majorpilot.content;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.ruoyi.majorpilot.shared.*;
import com.ruoyi.majorpilot.acceptance.LocalProductAccess;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.annotation.Profile;
import org.springframework.context.event.EventListener;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.transaction.support.TransactionTemplate;

@Service @Profile({"local","pilot"})
public final class TaskPublicationService {
    public record Validate(String manifestPath) {}
    public record Publish(Long expectedRevision,Map<String,Boolean> reviewChecks,String reasonText) {}
    public record Retire(Long expectedRevision,String reasonText) {}
    private final JdbcTemplate db;private final TransactionTemplate tx;private final TaskContentRepository repository;private final ObjectMapper mapper;private final boolean demoEnabled,previewEnabled;
    private LocalProductAccess local;
    @Autowired public void localProductAccess(LocalProductAccess local){this.local=local;}
    @Autowired
    public TaskPublicationService(JdbcTemplate db,TransactionTemplate tx,TaskContentRepository repository,ObjectMapper mapper,@Value("${MP_P2_DEMO_ENABLED:false}")boolean demoEnabled,@Value("${MP_CONTENT_PREVIEW_ENABLED:false}")boolean previewEnabled){this.db=db;this.tx=tx;this.repository=repository;this.mapper=mapper;this.demoEnabled=demoEnabled;this.previewEnabled=previewEnabled;}
    public TaskPublicationService(JdbcTemplate db,TransactionTemplate tx,TaskContentRepository repository,ObjectMapper mapper,boolean demoEnabled){this(db,tx,repository,mapper,demoEnabled,false);}
    @EventListener(ApplicationReadyEvent.class) public void installTechnicalDemos(){if(!demoEnabled)return;for(var bundle:repository.bundles())if(bundle.manifest().path("contentKind").asText().equals("DEMO"))tx.executeWithoutResult(status->{register(bundle);var row=lock(bundle.manifest().path("taskVersionId").asText());if(row.get("status").equals("DRAFT"))db.update("UPDATE mp_task_version SET status='PUBLISHED',published_at=UTC_TIMESTAMP(3),review_note='Bundled technical DEMO only; no professional review claimed',review_checks_json=?,row_version=row_version+1 WHERE id=?",json(Map.of("TECHNICAL_DEMO",true)),row.get("id"));});}
    @EventListener(ApplicationReadyEvent.class) public void installEngineeringPreviews(){if(!previewEnabled&&(local==null||!local.enabled()))return;for(var bundle:repository.bundles())if(bundle.manifest().path("contentKind").asText().equals("MAJOR")&&Set.of("task-manifest-v2","task-manifest-v3","task-manifest-v4","task-manifest-v5").contains(bundle.manifest().path("schemaVersion").asText()))tx.executeWithoutResult(status->{register(bundle);var row=lock(bundle.manifest().path("taskVersionId").asText());if(row.get("status").equals("DRAFT"))db.update("UPDATE mp_task_version SET status='REVIEW',review_note='Local content: schema, hashes and algorithm validated; human professional review and target-user timing PENDING',review_checks_json=?,row_version=row_version+1 WHERE id=?",json(Map.of("PROFESSIONAL_CORE",false,"TIMING_45_60",false)),row.get("id"));});}
    public List<Map<String,Object>> list(){return db.queryForList("SELECT public_id taskVersionId,content_kind contentKind,demo_key demoKey,version_code versionCode,status,manifest_sha256 manifestSha256,row_version revision FROM mp_task_version ORDER BY id DESC");}
    public Map<String,Object> validate(Validate input,long operator,String requestId){if(input==null||input.manifestPath()==null)throw new ApiException(422,"CONTENT_SCHEMA_INVALID");var bundle=repository.get(input.manifestPath());return tx.execute(status->{register(bundle);Map<String,Object> row=lock(bundle.manifest().path("taskVersionId").asText());if(row.get("status").equals("DRAFT")){db.update("UPDATE mp_task_version SET status='REVIEW',row_version=row_version+1,updated_at=UTC_TIMESTAMP(3) WHERE id=?",row.get("id"));audit(operator,row,"CONTENT_VALIDATE","Validated catalogued content",requestId,"REVIEW");}return view(lock(bundle.manifest().path("taskVersionId").asText()));});}
    public Map<String,Object> publish(String id,Publish input,long operator,String requestId){if(input==null||input.expectedRevision()==null||input.reviewChecks()==null)throw new ApiException(422,"CONTENT_REVIEW_REQUIRED");reason(input.reasonText());return tx.execute(status->{Map<String,Object> row=lock(id);revision(row,input.expectedRevision());if(!row.get("status").equals("REVIEW"))throw new ApiException(409,"CONTENT_STATE_CONFLICT");var bundle=repository.get(row.get("manifest_path").toString());Set<String> required=new HashSet<>();for(JsonNode key:bundle.manifest().at("/review/checkKeys"))required.add(key.asText());if(!input.reviewChecks().keySet().equals(required)||input.reviewChecks().values().stream().anyMatch(v->!Boolean.TRUE.equals(v)))throw new ApiException(422,"CONTENT_REVIEW_REQUIRED");
        List<Map<String,Object>> old=db.queryForList("SELECT * FROM mp_task_version WHERE lane_key=? AND status='PUBLISHED' FOR UPDATE",row.get("lane_key"));for(Map<String,Object> prior:old){db.update("UPDATE mp_task_version SET status='RETIRED',retired_at=UTC_TIMESTAMP(3),row_version=row_version+1 WHERE id=?",prior.get("id"));audit(operator,prior,"CONTENT_RETIRE","Superseded by reviewed version "+id,requestId,"RETIRED");}
        db.update("UPDATE mp_task_version SET status='PUBLISHED',published_at=UTC_TIMESTAMP(3),reviewed_by_operator_id=?,review_note=?,review_checks_json=?,row_version=row_version+1,updated_at=UTC_TIMESTAMP(3) WHERE id=?",operator,input.reasonText(),json(input.reviewChecks()),row.get("id"));audit(operator,row,"CONTENT_PUBLISH",input.reasonText(),requestId,"PUBLISHED");return view(lock(id));});}
    public Map<String,Object> retire(String id,Retire input,long operator,String requestId){if(input==null||input.expectedRevision()==null)throw new ApiException(422,"VALIDATION_ERROR");reason(input.reasonText());return tx.execute(status->{Map<String,Object> row=lock(id);revision(row,input.expectedRevision());if(!row.get("status").equals("PUBLISHED"))throw new ApiException(409,"CONTENT_STATE_CONFLICT");db.update("UPDATE mp_task_version SET status='RETIRED',retired_at=UTC_TIMESTAMP(3),row_version=row_version+1,updated_at=UTC_TIMESTAMP(3) WHERE id=?",row.get("id"));audit(operator,row,"CONTENT_RETIRE",input.reasonText(),requestId,"RETIRED");return view(lock(id));});}
    private void register(TaskContentRepository.Bundle b){JsonNode m=b.manifest();List<Map<String,Object>> rows=db.queryForList("SELECT * FROM mp_task_version WHERE public_id=? FOR UPDATE",m.path("taskVersionId").asText());if(!rows.isEmpty()){if(!b.manifestSha256().equals(rows.getFirst().get("manifest_sha256"))||!b.dataSha256().equals(rows.getFirst().get("data_sha256")))throw new ApiException(409,"CONTENT_VERSION_IMMUTABLE");return;}
        Long major=null;if(m.path("contentKind").asText().equals("MAJOR"))major=db.queryForObject("SELECT id FROM mp_major WHERE code=?",Long.class,m.path("majorCode").asText());
        db.update("INSERT INTO mp_task_version(public_id,content_kind,major_id,demo_key,version_code,status,manifest_path,manifest_sha256,data_sha256,content_schema_version,manifest_json) VALUES(?,?,?,?,?,'DRAFT',?,?,?,?,?)",m.path("taskVersionId").asText(),m.path("contentKind").asText(),major,m.path("demoKey").isNull()?null:m.path("demoKey").asText(),m.path("versionCode").asText(),b.path(),b.manifestSha256(),b.dataSha256(),m.path("schemaVersion").asText(),m.toString());}
    private Map<String,Object> lock(String id){List<Map<String,Object>> rows=db.queryForList("SELECT * FROM mp_task_version WHERE public_id=? FOR UPDATE",id);if(rows.size()!=1)throw new ApiException(404,"CONTENT_UNAVAILABLE");return rows.getFirst();}
    private static void revision(Map<String,Object> row,long expected){long actual=((Number)row.get("row_version")).longValue();if(expected!=actual)throw new ApiException(409,"REVISION_CONFLICT",Map.of("currentRevision",actual));}
    private static void reason(String reason){if(reason==null||reason.isBlank()||reason.length()>1000)throw new ApiException(422,"REASON_REQUIRED");}
    private Map<String,Object> view(Map<String,Object> row){return Map.of("taskVersionId",row.get("public_id"),"status",row.get("status"),"revision",row.get("row_version"),"manifestSha256",row.get("manifest_sha256"));}
    private void audit(long operator,Map<String,Object> before,String action,String reason,String requestId,String after){db.update("INSERT INTO mp_sensitive_audit(public_id,operator_id,action_code,target_type,target_public_id,reason_code,reason_text,before_summary_json,after_summary_json,correlation_id) VALUES(?,?,?,'TASK_VERSION',?,'CONTENT_REVIEW',?,?,?,?)",PublicIds.next(),operator,action,before.get("public_id"),reason,json(Map.of("status",before.get("status"))),json(Map.of("status",after)),requestId);}
    private String json(Object value){try{return mapper.writeValueAsString(value);}catch(Exception e){throw new ApiException(500,"SERIALIZATION_FAILED");}}
}
